  const handleRestoreRoutinesFromSnapshot = async () => {
    if (!requireEditorAccess("routines")) return;
    if (!user || !db) {
      showToast("클라우드 연결 후 스냅샷을 조회할 수 있습니다.");
      return;
    }
    try {
      const candidates = [];
      const bakSnap = await getDoc(getDocRef("family_meta_v4", "daily_routines_backup")).catch(() => null);
      if (bakSnap && bakSnap.exists() && Array.isArray(bakSnap.data()?.items)) {
        candidates.push({
          label: "직전 자동 백업",
          at: bakSnap.data()?.backedUpAt || "",
          items: bakSnap.data().items
        });
      }
      const snaps = await getDocs(getColRef("family_backups_v4")).catch(() => null);
      if (snaps) {
        snaps.forEach((d) => {
          const raw = d.data() || {};
          const list = raw?.data?.familyRoutines;
          if (Array.isArray(list) && list.length > 0) {
            candidates.push({
              label: raw.slot || d.id,
              at: raw.createdAt || "",
              items: list
            });
          }
        });
      }
      if (candidates.length === 0) {
        showToast("복원 가능한 클라우드 루틴 스냅샷이 없습니다.");
        return;
      }
      const maxLen = Math.max(...candidates.map((c) => c.items.length));
      const bestList = candidates
        .filter((c) => c.items.length >= Math.max(1, maxLen - 2))
        .sort((a, b) => String(b.at || "").localeCompare(String(a.at || "")) || b.items.length - a.items.length);
      const picked = bestList[0] || candidates[0];
      const ok = await askConfirm(
        `[${picked.label}] 클라우드 백업에서 루틴 ${picked.items.length}건을 복원할까요?\n(현재 목록 ${familyRoutines.length}건이 교체되며, 직전 상태는 백업됩니다.)`
      );
      if (!ok) return;
      const seen = new Set();
      const restored = picked.items.filter((r) => r && r.id && !seen.has(r.id) && seen.add(r.id));
      setFamilyRoutines(restored);
      await syncRoutinesToCloud(restored, { type: "replace" });
      recordActivity("루틴", "스냅샷 복원", `${picked.label} (${restored.length}건)`);
      showToast(`✅ [${picked.label}]에서 루틴 ${restored.length}건을 복원했습니다!`);
    } catch (e) {
      showToast(`⚠️ 루틴 복원 오류: ${e?.message || "조회 실패"}`);
    }
  };

  const syncRoutinesToCloud = async (nextList, op = null) => {
    try {
      localStorage.setItem("kim_family_routines_v1", JSON.stringify(nextList));
    } catch (e) {}
    if (user && db) {
      beginWrite();
      let ok = false;
      let errMsg = "";
      try {
        await runTransaction(db, async (tx) => {
          const ref = getDocRef("family_meta_v4", "daily_routines");
          const snap = await tx.get(ref);
          const serverItems =
            snap.exists() && Array.isArray(snap.data().items) ? snap.data().items : null;
          let merged = nextList;
          if (serverItems && op) {
            if (op.type === "upsert" && op.item) {
              const exists = serverItems.some((r) => r.id === op.item.id);
              merged = exists
                ? serverItems.map((r) => (r.id === op.item.id ? op.item : r))
                : [op.item, ...serverItems];
            } else if (op.type === "delete" && op.id) {
              merged = serverItems.filter((r) => r.id !== op.id);
            } else if (op.type === "replace") {
              merged = nextList;
            }
          } else if (serverItems && !op) {
            const todayStr = getTodayStr();
            const serverMap = new Map(serverItems.map((s) => [s.id, s]));
            const nextIds = new Set(nextList.map((it) => it.id));
            const updatedNext = nextList.map((item) => {
              const srv = serverMap.get(item.id);
              if (!srv) return item;
              const resetK =
                item.cycle === "weekly"
                  ? getIsoWeekKey(todayStr)
                  : item.cycle === "monthly" || item.cycle === "monthly_weekday"
                  ? todayStr.slice(0, 7)
                  : todayStr;
              if (!item.lastDoneKey && srv.lastDoneKey === resetK) {
                return {
                  ...item,
                  lastDoneKey: srv.lastDoneKey,
                  stepDoneKey: srv.stepDoneKey || item.stepDoneKey || "",
                  stepDoneIndices: Array.isArray(srv.stepDoneIndices) ? srv.stepDoneIndices : (item.stepDoneIndices || []),
                  ...(srv.skippedKey ? { skippedKey: srv.skippedKey } : {})
                };
              }
              if (!item.skippedKey && srv.skippedKey === resetK) {
                return { ...item, skippedKey: srv.skippedKey };
              }
              return item;
            });
            const preservedServer = serverItems.filter((s) => s && s.id && !nextIds.has(s.id));
            merged = [...updatedNext, ...preservedServer];
          }
          const seenRoutineIds = new Set();
          merged = (Array.isArray(merged) ? merged : []).filter((it) => {
            if (!it || !it.id || seenRoutineIds.has(it.id)) return false;
            seenRoutineIds.add(it.id);
            return true;
          });
          if (serverItems && serverItems.length > merged.length) {
            tx.set(
              getDocRef("family_meta_v4", "daily_routines_backup"),
              { items: serverItems, backedUpAt: new Date().toISOString() },
              { merge: true }
            );
          }
          tx.set(
            ref,
            { items: merged, initialized: true, updatedAt: new Date().toISOString() },
            { merge: true }
          );
        });
        ok = true;
      } catch (e) {
        errMsg = e?.message || "루틴 동기화 오류";
        setSyncErrorMsg(errMsg);
      } finally {
        endWrite(ok, errMsg);
      }
    }
  };


  const getRoutineResetKey = (rt, dayStr = currentDayKey) => {
    if (!rt) return dayStr;
    if (rt.cycle === "weekly") return getIsoWeekKey(dayStr);
    if (rt.cycle === "monthly" || rt.cycle === "monthly_weekday") return String(dayStr).slice(0, 7);
    return dayStr;
  };

  const getRoutineCarryOverInfo = (rt, dayStr = currentDayKey) => {
    if (!rt) return null;
    const dStr = String(dayStr || "").slice(0, 10);
    if (!dStr) return null;
    const resetKey = rt.cycle === "interval" ? dStr : getRoutineResetKey(rt, dStr);
    if (rt.skippedKey === resetKey || rt.skippedKey === dStr) return null;
    if (rt.cycle === "interval") return null;
    if (rt.lastDoneKey === resetKey) return null;
    if (rt.startDate && String(rt.startDate).slice(0, 10) > dStr) return null;

    // 전날(어제) 1일 치 미완료만 다음 날로 이월 (2일 이상 지난 다른 요일·일자 루틴이 엉뚱한 날에 뜨지 않도록 차단)
    const yesterdayStr = getOffsetDateStr(dStr, -1);
    const yDateObj = new Date(yesterdayStr + "T00:00:00");
    if (Number.isNaN(yDateObj.getTime())) return null;
    const yIsOff = isHolidayOrWeekend(yesterdayStr);
    const yAllowedSlots = getSlotLabelsForDayType(yIsOff);
    const yShortLabel = `${yDateObj.getMonth() + 1}/${yDateObj.getDate()}(${WEEKDAY_KO[yDateObj.getDay()]})`;

    const wasDueYesterday = (() => {
      if (rt.startDate && String(rt.startDate).slice(0, 10) > yesterdayStr) return false;
      if (!yAllowedSlots.includes(rt.timeSlot || "상시")) return false;
      if (!rt.cycle || rt.cycle === "daily") return true;
      if (rt.cycle === "weekdays") return !yIsOff;
      if (rt.cycle === "weekend_holiday") return yIsOff;
      if (rt.cycle === "weekly" && rt.weekDay !== undefined && rt.weekDay !== null) {
        return Number(rt.weekDay) === yDateObj.getDay();
      }
      if (rt.cycle === "monthly") {
        const lastDay = new Date(yDateObj.getFullYear(), yDateObj.getMonth() + 1, 0).getDate();
        const tgtDay = Math.min(Math.max(1, Number(rt.monthDay) || 1), lastDay);
        return tgtDay === yDateObj.getDate();
      }
      if (rt.cycle === "monthly_weekday") {
        const targetStr = getNthWeekdayDateStr(
          yDateObj.getFullYear(),
          yDateObj.getMonth() + 1,
          Number(rt.nthWeek) || 1,
          Number(rt.weekDay ?? 6)
        );
        return targetStr === yesterdayStr;
      }
      return false;
    })();

    if (!wasDueYesterday) return null;
    const yResetKey = getRoutineResetKey(rt, yesterdayStr);
    if (rt.lastDoneKey === yResetKey || rt.skippedKey === yResetKey || rt.skippedKey === yesterdayStr) return null;

    const todayIsOff = isHolidayOrWeekend(dStr);
    const todayAllowedSlots = getSlotLabelsForDayType(todayIsOff);
    const todayObj = new Date(dStr + "T00:00:00");
    const isNormallyDueToday = (() => {
      if (!todayAllowedSlots.includes(rt.timeSlot || "상시")) return false;
      if (!rt.cycle || rt.cycle === "daily") return true;
      if (rt.cycle === "weekdays") return !todayIsOff;
      if (rt.cycle === "weekend_holiday") return todayIsOff;
      if (rt.cycle === "weekly" && rt.weekDay !== undefined && rt.weekDay !== null) {
        return Number(rt.weekDay) === todayObj.getDay();
      }
      return false;
    })();

    if (!isNormallyDueToday) {
      return {
        isCarryOver: true,
        label: `어제 이월(${yShortLabel})`,
        sourceDateLabel: `어제 ${yShortLabel}`,
        missedDays: 1
      };
    }
    return {
      isCarryOver: false,
      wasMissedYesterday: true,
      label: "어제 미완료",
      sourceDateLabel: `어제 ${yShortLabel}`,
      missedDays: 1
    };
  };


  const getMonthlyRoutineDueInfo = (rt, dayStr = currentDayKey) => {
    if (!rt || (rt.cycle !== "monthly" && rt.cycle !== "monthly_weekday")) return null;
    const info = getRoutineNextDateInfo(rt, dayStr);
    return info ? { targetDay: rt.monthDay || 1, diff: info.diff, dateLabel: info.dateLabel } : null;
  };


  const getIntervalRoutineInfo = (rt, dayStr = currentDayKey) => {
    if (!rt || rt.cycle !== "interval") return null;
    const intervalDays = Math.max(2, Number(rt.intervalDays) || 2);
    if (!rt.lastDoneKey) return { done: false, daysLeft: 0, intervalDays };
    const lastD = new Date(String(rt.lastDoneKey).slice(0, 10) + "T00:00:00");
    const curD = new Date(String(dayStr).slice(0, 10) + "T00:00:00");
    if (Number.isNaN(lastD.getTime()) || Number.isNaN(curD.getTime())) {
      return { done: false, daysLeft: 0, intervalDays };
    }
    const elapsed = Math.floor((curD - lastD) / 86400000);
    const done = elapsed >= 0 && elapsed < intervalDays;
    return { done, daysLeft: Math.max(0, intervalDays - elapsed), intervalDays };
  };


  const isRoutineDoneNow = (rt) => {
    if (!rt) return false;
    if (rt.cycle === "interval") {
      return Boolean(getIntervalRoutineInfo(rt, currentDayKey)?.done);
    }
    return rt.lastDoneKey === getRoutineResetKey(rt, currentDayKey);
  };


  const isRoutineDueTodayOrPast = (rt, dayStr = currentDayKey) => {
    if (!rt) return false;
    const dStr = String(dayStr || "").slice(0, 10);
    if (rt.startDate && String(rt.startDate).slice(0, 10) > dStr) return false;
    const resetKey = rt.cycle === "interval" ? dStr : getRoutineResetKey(rt, dStr);
    if (rt.skippedKey === resetKey || rt.skippedKey === dStr) return false;
    const carryInfo = getRoutineCarryOverInfo(rt, dStr);
    if (carryInfo?.isCarryOver) return true;
    const allowedSlots = getSlotLabelsForDayType(isHolidayOrWeekend(dStr));
    if (!allowedSlots.includes(rt.timeSlot || "상시")) return false;
    if (!rt.cycle || rt.cycle === "daily") return true;
    if (rt.cycle === "weekdays") return !isHolidayOrWeekend(dStr);
    if (rt.cycle === "weekend_holiday") return isHolidayOrWeekend(dStr);
    if (rt.cycle === "interval") {
      const info = getIntervalRoutineInfo(rt, dStr);
      if (info?.done && rt.lastDoneKey !== dStr) return false;
      return true;
    }
    const base = new Date(dStr + "T00:00:00");
    if (Number.isNaN(base.getTime())) return true;
    if (rt.cycle === "weekly" && rt.weekDay !== undefined && rt.weekDay !== null) {
      return Number(rt.weekDay) === base.getDay();
    }
    if (rt.cycle === "monthly") {
      const y = base.getFullYear();
      const m = base.getMonth() + 1;
      const lastDay = new Date(y, m, 0).getDate();
      const tgtDay = Math.min(Math.max(1, Number(rt.monthDay) || 1), lastDay);
      return tgtDay === base.getDate();
    }
    if (rt.cycle === "monthly_weekday") {
      const targetStr = getNthWeekdayDateStr(
        base.getFullYear(),
        base.getMonth() + 1,
        Number(rt.nthWeek) || 1,
        Number(rt.weekDay ?? 6)
      );
      return targetStr === dStr;
    }
    return true;
  };


  const isRoutineDueOnExactDay = (rt, dayStr) => {
    if (!rt) return false;
    const dStr = String(dayStr || "").slice(0, 10);
    if (rt.startDate && String(rt.startDate).slice(0, 10) > dStr) return false;
    const allowedSlots = getSlotLabelsForDayType(isHolidayOrWeekend(dStr));
    if (!allowedSlots.includes(rt.timeSlot || "상시")) return false;
    if (!rt.cycle || rt.cycle === "daily") return true;
    if (rt.cycle === "weekdays") return !isHolidayOrWeekend(dStr);
    if (rt.cycle === "weekend_holiday") return isHolidayOrWeekend(dStr);
    const base = new Date(dStr + "T00:00:00");
    if (Number.isNaN(base.getTime())) return true;
    if (rt.cycle === "weekly" && rt.weekDay !== undefined && rt.weekDay !== null) {
      return Number(rt.weekDay) === base.getDay();
    }
    if (rt.cycle === "monthly") {
      const lastDay = new Date(base.getFullYear(), base.getMonth() + 1, 0).getDate();
      const tgtDay = Math.min(Math.max(1, Number(rt.monthDay) || 1), lastDay);
      return tgtDay === base.getDate();
    }
    if (rt.cycle === "monthly_weekday") {
      const targetStr = getNthWeekdayDateStr(
        base.getFullYear(),
        base.getMonth() + 1,
        Number(rt.nthWeek) || 1,
        Number(rt.weekDay ?? 6)
      );
      return targetStr === dStr;
    }
    if (rt.cycle === "interval") {
      if (!rt.lastDoneKey) return true;
      const intervalDays = Math.max(2, Number(rt.intervalDays) || 2);
      const lastD = new Date(String(rt.lastDoneKey).slice(0, 10) + "T00:00:00");
      if (Number.isNaN(lastD.getTime())) return true;
      const elapsed = Math.floor((base - lastD) / 86400000);
      return elapsed === 0 || elapsed >= intervalDays;
    }
    return true;
  };


  const isRoutineDoneOnDay = (rt, dayStr) => {
    if (!rt) return false;
    const dStr = String(dayStr || "").slice(0, 10);
    if (rt.cycle === "interval") {
      if (!rt.lastDoneKey) return false;
      const intervalDays = Math.max(2, Number(rt.intervalDays) || 2);
      const lastD = new Date(String(rt.lastDoneKey).slice(0, 10) + "T00:00:00");
      const curD = new Date(dStr + "T00:00:00");
      if (Number.isNaN(lastD.getTime()) || Number.isNaN(curD.getTime())) return false;
      const elapsed = Math.floor((curD - lastD) / 86400000);
      return elapsed >= 0 && elapsed < intervalDays;
    }
    return rt.lastDoneKey === getRoutineResetKey(rt, dStr);
  };


  const handleToggleRoutine = (rtId) => {
    if (!requireEditorAccess("routines")) return;
    const todayKey = getTodayStr();
    if (todayKey !== currentDayKey) setCurrentDayKey(todayKey);
    let wasDone = false;
    let targetTitle = "";
    const nextList = familyRoutines.map((r) => {
      if (r.id !== rtId) return r;
      targetTitle = r.title || "루틴";
      const steps = parseRoutineSteps(r.title);
      if (r.cycle === "interval") {
        const info = getIntervalRoutineInfo(r, todayKey);
        wasDone = Boolean(info?.done);
        return {
          ...r,
          lastDoneKey: wasDone ? "" : todayKey,
          skippedKey: "",
          ...(steps.length >= 2 ? { stepDoneKey: todayKey, stepDoneIndices: wasDone ? [] : steps.map((_, idx) => idx) } : {})
        };
      }
      const targetKey = getRoutineResetKey(r, todayKey);
      wasDone = r.lastDoneKey === targetKey;
      return {
        ...r,
        lastDoneKey: wasDone ? "" : targetKey,
        skippedKey: "",
        ...(steps.length >= 2 ? { stepDoneKey: targetKey, stepDoneIndices: wasDone ? [] : steps.map((_, idx) => idx) } : {})
      };
    });
    setFamilyRoutines(nextList);
    recordActivity("루틴", wasDone ? "해제" : "완료", targetTitle);
    showToast(wasDone ? `↩️ '${targetTitle}' 완료를 취소했습니다.` : `✅ '${targetTitle}' 루틴 완료!`);
    const updatedItem = nextList.find((r) => r.id === rtId);
    syncRoutinesToCloud(nextList, updatedItem ? { type: "upsert", item: updatedItem } : null);
  };


