  const handleAddRoutine = (overrideTitle = null) => {
    if (!requireEditorAccess("routines")) return;
    const safeOverride = typeof overrideTitle === "string" ? overrideTitle : null;
    const title = String(safeOverride !== null ? safeOverride : (routineTitleLiveRef.current || newRoutineTitle || "")).trim();
    if (!title) return;
    const cycleVal = ["daily", "weekdays", "weekend_holiday", "interval", "weekly", "monthly", "monthly_weekday"].includes(newRoutineCycle)
      ? newRoutineCycle
      : "daily";
    const mDayVal = cycleVal === "monthly" ? Math.min(31, Math.max(1, Number(newRoutineMonthDay) || 1)) : null;
    const iDaysVal = cycleVal === "interval" ? Math.min(30, Math.max(2, Number(newRoutineIntervalDays) || 2)) : null;
    const nthVal = cycleVal === "monthly_weekday" ? Number(newRoutineNthWeek) || 1 : null;
    const wdVal =
      cycleVal === "weekly" && newRoutineWeekDay !== "any"
        ? Number(newRoutineWeekDay)
        : cycleVal === "monthly_weekday"
        ? Number(newRoutineWeekDay === "any" ? 6 : newRoutineWeekDay)
        : null;
    const schedTimeVal = /^\d{2}:\d{2}$/.test(String(newRoutineScheduledTime || "").trim())
      ? String(newRoutineScheduledTime).trim()
      : "";
    if (
      familyRoutines.some(
        (r) =>
          r.id !== editingRoutineId &&
          String(r.title || "").trim().toLowerCase() === title.toLowerCase() &&
          r.cycle === cycleVal &&
          (r.timeSlot || "상시") === newRoutineTimeSlot &&
          (r.scheduledTime || "") === schedTimeVal &&
          (r.assignee || "공통") === (newRoutineAssignee || "공통")
      )
    ) {
      showToast("이미 같은 대상·이름·시간대·주기의 루틴이 등록되어 있습니다.");
      return;
    }
    if (editingRoutineId) {
      const nextList = familyRoutines.map((r) => {
        if (r.id !== editingRoutineId) return r;
        return {
          id: r.id,
          title,
          cycle: cycleVal,
          timeSlot: newRoutineTimeSlot || "상시",
          ...(schedTimeVal ? { scheduledTime: schedTimeVal } : {}),
          ...(cycleVal === "interval" ? { intervalDays: iDaysVal } : {}),
          ...(cycleVal === "monthly" ? { monthDay: mDayVal } : {}),
          ...(cycleVal === "monthly_weekday" ? { nthWeek: nthVal, weekDay: wdVal } : {}),
          ...(cycleVal === "weekly" && wdVal !== null ? { weekDay: wdVal } : {}),
          assignee: newRoutineAssignee || "공통",
          lastDoneKey: r.lastDoneKey || "",
          ...(r.startDate ? { startDate: r.startDate } : {}),
          ...(r.skippedKey ? { skippedKey: r.skippedKey } : {}),
          ...(r.title === title && r.stepDoneKey ? { stepDoneKey: r.stepDoneKey, stepDoneIndices: r.stepDoneIndices || [] } : {})
        };
      });
      const editedItem = nextList.find((r) => r.id === editingRoutineId);
      const finalEditedItem = editedItem
        ? { ...editedItem, ...(newRoutineAttachments.length > 0 ? { attachments: newRoutineAttachments } : {}) }
        : null;
      const finalNextList = finalEditedItem
        ? nextList.map((r) => (r.id === editingRoutineId ? finalEditedItem : r))
        : nextList;
      setFamilyRoutines(finalNextList);
      setEditingRoutineId(null);
      routineTitleLiveRef.current = "";
    setNewRoutineTitle("");
      setNewRoutineScheduledTime("");
      setNewRoutineAttachments([]);
      setIsRoutineModalOpen(false);
      syncRoutinesToCloud(finalNextList, finalEditedItem ? { type: "upsert", item: finalEditedItem } : null);
      showToast(`✏️ '${title}' 루틴이 수정되었습니다!`);
      return;
    }
    const nextItem = {
      id: `rt-${Date.now()}`,
      title,
      cycle: cycleVal,
      timeSlot: newRoutineTimeSlot || "상시",
      ...(schedTimeVal ? { scheduledTime: schedTimeVal } : {}),
      ...(cycleVal === "interval" ? { intervalDays: iDaysVal } : {}),
      ...(cycleVal === "monthly" ? { monthDay: mDayVal } : {}),
      ...(cycleVal === "monthly_weekday" ? { nthWeek: nthVal, weekDay: wdVal } : {}),
      ...(cycleVal === "weekly" && wdVal !== null ? { weekDay: wdVal } : {}),
      assignee: newRoutineAssignee || "공통",
      startDate: getTodayStr(),
      ...(newRoutineAttachments.length > 0 ? { attachments: newRoutineAttachments } : {}),
      lastDoneKey: ""
    };
    const nextList = [nextItem, ...familyRoutines];
    setFamilyRoutines(nextList);
    routineTitleLiveRef.current = "";
    setNewRoutineTitle("");
    setNewRoutineScheduledTime("");
    setNewRoutineAttachments([]);
    setIsRoutineModalOpen(false);
    syncRoutinesToCloud(nextList, { type: "upsert", item: nextItem });
    recordActivity("루틴", "추가", title);
    showToast(`🔄 '${title}' 루틴이 추가되었습니다!`);
  };


