  const handleCopyTodayBriefing = async () => {
    const today = getTodayStr();
    const linesOut = [`🏡 [우리 가족 오늘 브리핑 · ${today}]`];
    if (weatherInfo) {
      linesOut.push(`🌤️ 날씨: ${weatherInfo.temp}°C (${weatherInfo.min}°/${weatherInfo.max}°) · ${weatherInfo.rainBarText || "☔ 0%"} · 미세 ${weatherInfo.pm10}(${weatherInfo.dust?.label || "-"})`);
      if (weatherInfo.hasUpcomingRain && weatherInfo.rainAlertText) {
        linesOut.push(weatherInfo.rainAlertText);
      }
    }
    if (canViewTab("daily")) {
      const todayMeals = meals.filter((m) => m.date === today);
      if (todayMeals.length > 0) {
        linesOut.push(`🍽️ 오늘 식단: ${todayMeals.map((m) => `${m.slot}(${m.menu})`).join(" / ")}`);
      }
    }
    if (canViewTab("schedule")) {
      const todaySch = getSchedulesForDate(today)
        .filter((s) => !s.done)
        .sort((a, b) => String(a.time || "99:99").localeCompare(String(b.time || "99:99")));
      if (todaySch.length > 0) {
        linesOut.push(
          `🗓️ 오늘 일정·할일: ${todaySch
            .map((s) => `${s.time ? `⏰${formatRoutineTimeLabel(s.time)} ` : ""}${s.title}${s.location ? `(${s.location})` : ""}`)
            .join(", ")}`
        );
      }
    }
    if (canViewTab("routines")) {
      const pendingRoutines = familyRoutines
        .filter((r) => isRoutineDueTodayOrPast(r, today) && !isRoutineDoneNow(r))
        .sort((a, b) => String(a.scheduledTime || "99:99").localeCompare(String(b.scheduledTime || "99:99")));
      if (pendingRoutines.length > 0) {
        const previewRt = pendingRoutines
          .slice(0, 5)
          .map((r) => {
            const cTag = getRoutineCarryOverInfo(r, today)?.isCarryOver ? "[이월] " : "";
            return `${cTag}${r.scheduledTime ? `⏰${formatRoutineTimeLabel(r.scheduledTime)} ` : ""}${r.title}`;
          });
        linesOut.push(`🔄 남은 루틴(${pendingRoutines.length}건): ${previewRt.join(", ")}`);
      }
    }
    if (canViewTab("fridge") && expiringItems.length > 0) {
      linesOut.push(`❄️ 임박 재료: ${expiringItems.slice(0, 5).map((f) => `${f.name}(${f.diff < 0 ? "만료" : `D-${f.diff}`})`).join(", ")}`);
    }
    if (canViewTab("shopping")) {
      const unchk = shoppingList.filter((s) => !s.checked);
      if (unchk.length > 0) {
        linesOut.push(`🛒 장보기(${unchk.length}건): ${unchk.slice(0, 6).map((s) => s.name).join(", ")}`);
      }
    }
    if (canViewTab("house")) {
      const dueHouse = houseItems.filter((it) => {
        const dt = it.kind === "warranty" ? it.warrantyEnd : it.kind === "medicine" ? it.expiryDate : "";
        return dt && getDaysDiff(dt) <= 7;
      });
      if (dueHouse.length > 0) {
        linesOut.push(
          `🏠 상비약·A/S 만료임박(${dueHouse.length}건): ${dueHouse
            .slice(0, 4)
            .map((it) => {
              const df = getDaysDiff(it.kind === "warranty" ? it.warrantyEnd : it.expiryDate);
              return `${it.title}(${df < 0 ? "만료" : df === 0 ? "오늘 만료" : `D-${df}`})`;
            })
            .join(", ")}`
        );
      }
    }
    const textOut = linesOut.join("\n");
    await copyTextSafe(textOut, "📋 오늘 가족 브리핑이 복사되었습니다! (카톡에 바로 붙여넣기)");
  };


