  const getDiaryEntryChildIds = (entry) => {
    if (Array.isArray(entry?.childIds) && entry.childIds.length > 0) return entry.childIds;
    if (entry?.childId === "시목·시율") return ["시목", "시율"];
    return [entry?.childId || "시율"];
  };


