  const handleClearCheckedShopping = async () => {
    if (!requireEditorAccess()) return;
    const checkedItems = shoppingList.filter((s) => s.checked);
    if (checkedItems.length === 0) return;
    const checkedIds = new Set(checkedItems.map((s) => s.id));
    setShoppingList((prev) => prev.filter((s) => !checkedIds.has(s.id)));
    if (user && db) {
      beginWrite();
      try {
        for (let i = 0; i < checkedItems.length; i += 200) {
          const batch = writeBatch(db);
          checkedItems.slice(i, i + 200).forEach((s) => batch.delete(getDocRef("family_shopping_v4", s.id)));
          await batch.commit();
        }
        showToast(`🧹 체크 완료된 장보기 ${checkedItems.length}건을 비웠습니다.`);
      } catch (e) {
        setSyncErrorMsg(e?.message || "장보기 일괄 삭제 오류");
      } finally {
        endWrite();
      }
    }
  };


  const handleMoveCheckedShoppingToFridge = async () => {
    if (!requireEditorAccess("shopping")) return;
    const checkedItems = shoppingList.filter((s) => s.checked);
    if (checkedItems.length === 0) return;
    const todayStr = getTodayStr();
    const defaultExp = getOffsetDateStr(todayStr, 7);
    const createdItems = [];
    checkedItems.forEach((s, idx) => {
      const fId = `f-shop-${Date.now()}-${idx}`;
      const cat = s.category || fridgeCategories[0] || "기타";
      const loc = cat.includes("냉동") ? "메인 냉동실" : (cat.includes("양념") || cat.includes("곡물") || cat.includes("음료")) ? "실온·팬트리" : "냉장실";
      const rawQty = String(s.quantity || "").trim();
      const qMatch = rawQty.match(/^(\d+(?:\.\d+)?)\s*(.*)$/);
      const parsedQty = qMatch ? (Number(qMatch[1]) || 1) : 1;
      const parsedUnit = qMatch && qMatch[2] ? qMatch[2].trim() : "개";
      createdItems.push({
        id: fId,
        name: s.name,
        category: cat,
        location: loc,
        qty: parsedQty,
        quantity: parsedQty,
        unit: parsedUnit,
        expiryDate: defaultExp,
        purchaseDate: todayStr,
        memo: s.memo || "장보기 완료 자동입고",
        updatedAt: new Date().toISOString()
      });
    });
    const checkedIds = new Set(checkedItems.map((s) => s.id));
    setFridgeMap((prev) => {
      const nextLocal = { ...(prev.local || {}) };
      createdItems.forEach((it) => {
        nextLocal[it.id] = it;
      });
      return { ...prev, local: nextLocal };
    });
    setShoppingList((prev) => prev.filter((s) => !checkedIds.has(s.id)));
    if (user && db) {
      beginWrite();
      try {
        for (let i = 0; i < createdItems.length; i += 150) {
          const batch = writeBatch(db);
          createdItems.slice(i, i + 150).forEach((it) => batch.set(getDocRef("family_fridge_v4", it.id), it));
          checkedItems.slice(i, i + 150).forEach((s) => batch.delete(getDocRef("family_shopping_v4", s.id)));
          await batch.commit();
        }
        recordActivity("냉장고", "장보기입고", `${createdItems.length}건 냉장고 이동`);
        showToast(`❄️ 담은 품목 ${createdItems.length}건을 냉장고에 바로 넣었습니다!`);
      } catch (e) {
        setSyncErrorMsg(e?.message || "장보기 냉장고 이동 오류");
        showToast("⚠️ 냉장고 일괄 입고 중 오류가 발생했습니다.");
      } finally {
        endWrite();
      }
    } else {
      showToast(`❄️ 담은 품목 ${createdItems.length}건을 냉장고에 넣었습니다!`);
    }
  };


  const handleQuickUpdateFridgeExpiry = async (item, nextExpiryDate, presetLabel = "") => {
    if (!requireEditorAccess("fridge") || !item?.id || !nextExpiryDate) return;
    const updated = { ...item, expiryDate: nextExpiryDate, updatedAt: Date.now() };
    setFridgeMap((prev) => {
      const nextLocal = { ...(prev.local || {}), [item.id]: updated };
      return { ...prev, local: nextLocal };
    });
    setQuickFridgeItem((prev) => (prev && prev.id === item.id ? updated : prev));
    if (user && db) {
      beginWrite();
      let ok = false;
      let errMsg = "";
      try {
        const batch = writeBatch(db);
        batch.set(getDocRef("family_fridge_v4", item.id), updated, { merge: true });
        if (fridgeMap.src_1?.[item.id]) {
          batch.set(getDocRef("family_fridge_v3", item.id), updated, { merge: true });
        }
        await batch.commit();
        ok = true;
      } catch (e) {
        errMsg = e?.message || "소비기한 변경 동기화 오류";
      } finally {
        endWrite(ok, errMsg);
      }
    }
    recordActivity("냉장고", "소비기한 변경", `${item.name} → ${nextExpiryDate}`);
    showToast(`📅 ${item.name} 소비기한을 ${presetLabel ? `${presetLabel}(${nextExpiryDate})` : nextExpiryDate}로 변경했습니다.`);
  };


  const handleConfirmStockIn = async () => {
    if (!requireEditorAccess()) return;
    if (!stockInItem) return;
    const fId = `f-${Date.now()}`;
    const priceNum = Number(stockInPrice) || 0;
    const expDateObj = new Date();
    expDateObj.setDate(expDateObj.getDate() + 10);


    const rawQtyStr = String(stockInItem.quantity || "1개").trim();
    const qtyMatch = rawQtyStr.match(/^(\d+(?:\.\d+)?)\s*(.*)$/);
    const parsedQty = qtyMatch && Number(qtyMatch[1]) > 0 ? Number(qtyMatch[1]) : 1;
    const parsedUnit = (qtyMatch && qtyMatch[2] ? qtyMatch[2].trim() : "") || "개";
    const itemLoc = fridgeLocations.includes(stockInLocation) ? stockInLocation : (fridgeLocations[0] || "냉장실");
    const itemCat = stockInItem.category || "채소/과일";
    const autoZone = resolveItemShelfZone({ location: itemLoc, category: itemCat });
    const defaultExp = getDefaultExpiryForLocation(itemLoc);


    const newFridgeItem = {
      id: fId,
      name: stockInItem.name,
      location: itemLoc,
      shelfZone: autoZone,
      category: itemCat,
      quantity: parsedQty,
      unit: parsedUnit,
      expiryDate: stockInExpiry || defaultExp || formatDate(expDateObj),
      price: priceNum,
      purchaseDate: selectedDate
    };


    setFridgeMap((prev) => ({
      ...prev,
      local: { ...(prev.local || {}), [fId]: newFridgeItem }
    }));
    setShoppingList((prev) => prev.filter((s) => s.id !== stockInItem.id));


    const stockLockKey = `stockin-${stockInItem.id}`;
    if (inFlightOpsRef.current.has(stockLockKey)) return;
    inFlightOpsRef.current.add(stockLockKey);
    if (user && db) {
      beginWrite();
      let ok = false;
      let errMsg = "";
      try {
        await runTransaction(db, async (tx) => {
          const shopRef = getDocRef("family_shopping_v4", stockInItem.id);
          const shopSnap = await tx.get(shopRef);
          if (!shopSnap.exists()) {
            throw new Error("이미 입고 완료되었거나 삭제된 장보기 항목입니다.");
          }
          tx.set(getDocRef("family_fridge_v3", fId), newFridgeItem);
          tx.set(getDocRef("family_fridge_v4", fId), newFridgeItem);
          tx.delete(shopRef);
          if (priceNum > 0) {
            const expId = `exp-${fId}`;
            tx.set(getDocRef("family_expenses_v4", expId), {
              id: expId,
              title: newFridgeItem.name,
              category: newFridgeItem.category,
              amount: priceNum,
              date: selectedDate,
              type: "장보기/식재료"
            });
          }
        });
        recordActivity("냉장고", "장보기입고", `${newFridgeItem.name} (0 → ${parsedQty}${parsedUnit})`);
        ok = true;
      } catch (e) {
        errMsg = e?.message || "장보기 입고 동기화 오류";
        setSyncErrorMsg(errMsg);
        showToast(`⚠️ ${errMsg}`);
      } finally {
        inFlightOpsRef.current.delete(stockLockKey);
        endWrite(ok, errMsg);
      }
    } else {
      inFlightOpsRef.current.delete(stockLockKey);
    }
    setStockInItem(null);
    setStockInPrice("");
    setStockInLocation("냉장실");
    showToast("구매 완료! 냉장고 입고 및 식비 가계부에 반영되었습니다.");
  };


