  const handleApplyMarkdownPaste = async (page, rawMarkdown, mode = "append", headingColor = "amber") => {
    if (!requireEditorAccess("pages") || !page) return;
    const parsed = parseNotionMarkdownToBlocks(rawMarkdown, headingColor);
    if (parsed.length === 0) {
      showToast("붙여넣을 내용이 비어 있습니다.");
      return;
    }
    const existing = Array.isArray(page.blocks) ? page.blocks : [];
    const nextBlocks = mode === "replace" ? parsed : [...existing, ...parsed];
    await savePageToCloud({
      ...page,
      blocks: nextBlocks,
      updatedAtMs: Date.now()
    });
    setIsPagePasteModalOpen(false);
    setPagePasteText("");
    const hCnt = parsed.filter((b) => b.type === "heading").length;
    const tCnt = parsed.filter((b) => b.type === "todo").length;
    const tblCnt = parsed.filter((b) => b.type === "md_table").length;
    const summaryParts = [
      hCnt > 0 ? `섹션 ${hCnt}` : "",
      tCnt > 0 ? `체크 ${tCnt}` : "",
      tblCnt > 0 ? `표 ${tblCnt}` : ""
    ].filter(Boolean).join(" · ") || `${parsed.length}개 블록`;
    recordActivity("노트", "일괄붙여넣기", `${page.title} (${summaryParts})`);
    showToast(`✨ ${summaryParts} 자동 반영되었습니다!`);
  };

  const handleInsertPageBlockAt = async (page, blockType = "todo", afterBlockId = null) => {
    if (!requireEditorAccess("pages") || !page) return;
    const nowMs = Date.now();
    let curBlocks = Array.isArray(page.blocks) ? [...page.blocks] : [];
    // Flush currently edited block text if any
    if (editingBlockId) {
      const cleanCur = String(editingBlockText || "").trim();
      curBlocks = curBlocks.map((b) => (b.id === editingBlockId ? { ...b, text: cleanCur || b.text } : b));
    }
    const afterBlk = afterBlockId ? curBlocks.find((b) => b.id === afterBlockId) : null;
    const newId = `blk-${nowMs}-${Math.random().toString(36).slice(2, 5)}`;
    const newBlock = {
      id: newId,
      type: blockType,
      text: "",
      ...(blockType === "todo" ? { checked: false } : {}),
      ...(blockType === "heading" ? { color: "amber" } : {}),
      ...(blockType !== "heading" && afterBlk && afterBlk.type !== "heading" && Number(afterBlk.indent) > 0
        ? { indent: Number(afterBlk.indent) }
        : {})
    };
    const targetIdx = afterBlockId ? curBlocks.findIndex((b) => b.id === afterBlockId) : -1;
    if (targetIdx >= 0) {
      curBlocks.splice(targetIdx + 1, 0, newBlock);
    } else {
      curBlocks.push(newBlock);
    }
    setIsPageVisualEditMode(true);
    setEditingBlockId(newId);
    setEditingBlockText("");
    await savePageToCloud({ ...page, blocks: curBlocks, updatedAtMs: nowMs });
  };

  const handleFinishPageVisualEdit = async (page) => {
    if (editingBlockId && page) {
      const clean = String(editingBlockText || "").trim();
      const curBlocks = Array.isArray(page.blocks) ? page.blocks : [];
      const nextBlocks = clean
        ? curBlocks.map((b) => (b.id === editingBlockId ? { ...b, text: clean } : b))
        : curBlocks.filter((b) => b.id !== editingBlockId);
      await savePageToCloud({ ...page, blocks: nextBlocks, updatedAtMs: Date.now() });
    }
    setEditingBlockId(null);
    setIsPageVisualEditMode(false);
    setIsPageMultiSelectMode(false);
    setSelectedPageBlockIds([]);
  };

  const handleSelectOrSwitchPageBlock = async (page, targetBlk) => {
    if (!canEditTab("pages") || !page || !targetBlk) return;
    if (isPageMultiSelectMode) {
      setSelectedPageBlockIds((prev) =>
        prev.includes(targetBlk.id) ? prev.filter((id) => id !== targetBlk.id) : [...prev, targetBlk.id]
      );
      return;
    }
    if (editingBlockId && editingBlockId !== targetBlk.id) {
      const cleanPrev = String(editingBlockText || "").trim();
      const curBlocks = Array.isArray(page.blocks) ? page.blocks : [];
      const prevBlk = curBlocks.find((b) => b.id === editingBlockId);
      if (prevBlk && prevBlk.text !== cleanPrev) {
        const nextBlocks = cleanPrev
          ? curBlocks.map((b) => (b.id === editingBlockId ? { ...b, text: cleanPrev } : b))
          : curBlocks.filter((b) => b.id !== editingBlockId);
        savePageToCloud({ ...page, blocks: nextBlocks, updatedAtMs: Date.now() });
      }
    }
    setIsPageVisualEditMode(true);
    setEditingBlockId(targetBlk.id);
    setEditingBlockText(targetBlk.text || "");
  };

  const handleApplyPageBlocksStyle = async (page, targetIds, stylePatch) => {
    if (!requireEditorAccess("pages") || !page || !Array.isArray(targetIds) || targetIds.length === 0) return;
    const idSet = new Set(targetIds);
    const nextBlocks = (Array.isArray(page.blocks) ? page.blocks : []).map((b) => {
      if (!idSet.has(b.id)) return b;
      const patch = typeof stylePatch === "function" ? stylePatch(b) : stylePatch;
      return { ...b, ...patch };
    });
    await savePageToCloud({ ...page, blocks: nextBlocks, updatedAtMs: Date.now() });
  };

  const handleBulkIndentPageBlocks = async (page, targetIds, delta) => {
    if (!requireEditorAccess("pages") || !page || !Array.isArray(targetIds) || targetIds.length === 0) return;
    const idSet = new Set(targetIds);
    const nextBlocks = (Array.isArray(page.blocks) ? page.blocks : []).map((b) => {
      if (!idSet.has(b.id) || b.type === "heading") return b;
      const nextIndent = Math.max(0, Math.min(3, (Number(b.indent) || 0) + delta));
      return { ...b, indent: nextIndent };
    });
    await savePageToCloud({ ...page, blocks: nextBlocks, updatedAtMs: Date.now() });
  };

  const handleBulkDeletePageBlocks = async (page, targetIds) => {
    if (!requireEditorAccess("pages") || !page || !Array.isArray(targetIds) || targetIds.length === 0) return;
    const idSet = new Set(targetIds);
    const nextBlocks = (Array.isArray(page.blocks) ? page.blocks : []).filter((b) => !idSet.has(b.id));
    if (editingBlockId && idSet.has(editingBlockId)) setEditingBlockId(null);
    setSelectedPageBlockIds((prev) => prev.filter((id) => !idSet.has(id)));
    await savePageToCloud({ ...page, blocks: nextBlocks, updatedAtMs: Date.now() });
  };
  const normalizeDreamUrl = (raw) => {
    const s = String(raw || "").trim();
    if (!s) return "";
    if (/^https?:\/\//i.test(s)) return s;
    return `https://${s}`;
  };

  const saveHouseStorageRoomsToCloud = async (nextRooms, toastMsg = "") => {
    const clean = Array.from(new Set((Array.isArray(nextRooms) ? nextRooms : []).map((s) => String(s || "").trim()).filter(Boolean)));
    if (clean.length === 0) return;
    setHouseStorageRooms(clean);
    try { localStorage.setItem("kim_house_storage_rooms_v1", JSON.stringify(clean)); } catch (e) {}
    if (user && db) {
      try {
        await setDoc(getDocRef("family_meta_v4", "house_rooms_v1"), {
          rooms: clean,
          updatedAtMs: Date.now()
        }, { merge: true });
      } catch (e) {
        setSyncErrorMsg(e?.message || "수납 장소 저장 오류");
      }
    }
    if (toastMsg) showToast(toastMsg);
  };

  const handleRenameHouseStorageRoom = async (oldName, rawNewName) => {
    if (!requireEditorAccess("house")) return;
    const nextName = String(rawNewName || "").trim();
    if (!nextName || nextName === oldName) {
      setEditingHouseRoomOrig("");
      setEditingHouseRoomDraft("");
      return;
    }
    if (houseStorageRooms.includes(nextName)) {
      return showToast(`'${nextName}' 장소가 이미 있습니다.`);
    }
    const nextRooms = houseStorageRooms.map((r) => (r === oldName ? nextName : r));
    await saveHouseStorageRoomsToCloud(nextRooms, `📍 '${oldName}' → '${nextName}' 변경했습니다.`);
    if (houseForm.room === oldName) setHouseForm((p) => ({ ...p, room: nextName }));
    if (houseFilter === oldName) setHouseFilter(nextName);
    // Sync existing storage items using the renamed room
    const affected = houseItems.filter((it) => it.kind === "storage" && it.room === oldName);
    if (affected.length > 0) {
      setHouseItems((prev) => prev.map((it) => (it.kind === "storage" && it.room === oldName ? { ...it, room: nextName } : it)));
      if (user && db) {
        try {
          await Promise.all(
            affected.map((it) =>
              setDoc(getDocRef("family_house_items_v1", it.id), { ...it, room: nextName, updatedAtMs: Date.now() }, { merge: true })
            )
          );
        } catch (e) {
          setSyncErrorMsg(e?.message || "수납 장소 일괄 변경 동기화 오류");
        }
      }
    }
    setEditingHouseRoomOrig("");
    setEditingHouseRoomDraft("");
  };

  const handleDeleteHouseStorageRoom = async (targetRoom) => {
    if (!requireEditorAccess("house")) return;
    if (houseStorageRooms.length <= 1) {
      return showToast("최소 1개의 장소는 남겨두어야 합니다.");
    }
    const nextRooms = houseStorageRooms.filter((r) => r !== targetRoom);
    await saveHouseStorageRoomsToCloud(nextRooms, `🗑️ '${targetRoom}' 장소를 삭제했습니다.`);
    if (houseForm.room === targetRoom) setHouseForm((p) => ({ ...p, room: nextRooms[0] || "기타" }));
    if (houseFilter === targetRoom) setHouseFilter("전체");
  };

