                const fallbackElapsed = Number.isFinite(origMs) ? Math.floor((todayMs - origMs) / 86400000) + 1 : null;
                const elapsedDays = calc.elapsedDays ?? (fallbackElapsed && fallbackElapsed > 0 ? fallbackElapsed : null);
