                        setRecipeCatFilter("전체");
                        setRecipeDiffFilter("전체");
                        setRecipeSearch(kw);
                        setActiveTab("recipes");
                        showToast(`📖 레시피북에서 '${kw}' 활용 요리를 검색합니다.`);
