                            const lVal = Math.max(0, Number(e.target.value) || 0);
                            const rVal = Math.max(0, Number(p.rightMin) || 0);
                            const nextDur = lVal + rVal;
                            return {
                              ...p,
                              leftMin: e.target.value,
                              durationMin: nextDur,
                              endMs: p.startMs ? Number(p.startMs) + nextDur * 60000 : p.endMs
                            };
